datasource db {
  provider = "sqlite"
  // Wasp requires that the url is set to the DATABASE_URL environment variable.
  url      = env("DATABASE_URL")
}

// Wasp requires the `prisma-client-js` generator to be present.
generator client {
  provider = "prisma-client-js"
}

model Project {
  id    Int    @id @default(autoincrement())
  name  String
  tasks Task[]
}

model Task {
  id        Int     @id @default(autoincrement())
  title     String
  done      Boolean @default(false)
  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)
  projectId Int
}

app taskboard {
  wasp: {
    version: "^0.16.7"
  },
  title: "taskboard",
  db: {
    seeds: [
      import { devSeed } from "@src/dbSeeds"
    ]
  }
}

route RootRoute { path: "/", to: MainPage }
page MainPage {
  component: import { MainPage } from "@src/MainPage"
}

query getTasks {
  fn: import { getTasks } from "@src/queries",
  entities: [Task]
}

query getProjectStats {
  fn: import { getProjectStats } from "@src/queries",
  entities: [Project]
}

action addTask {
  fn: import { addTask } from "@src/actions",
  entities: [Task]
}

action toggleTask {
  fn: import { toggleTask } from "@src/actions",
  entities: [Task]
}

export const getTasks = async (args, context) => {
  return context.entities.Task.findMany({
    orderBy: { id: 'asc' }
  });
};

export const getProjectStats = async (args, context) => {
  const projects = await context.entities.Project.findMany({
    include: {
      tasks: true
    },
    orderBy: { id: 'asc' }
  });

  return projects.map(project => {
    const totalTasks = project.tasks.length;
    const doneTasks = project.tasks.filter(t => t.done).length;
    return {
      id: project.id,
      name: project.name,
      totalTasks,
      doneTasks
    };
  });
};

export const addTask = async (args, context) => {
  const { title, projectId } = args;
  if (!title) {
    throw new Error("Title is required.");
  }
  if (!projectId) {
    throw new Error("projectId is required.");
  }
  return context.entities.Task.create({
    data: {
      title,
      projectId: Number(projectId),
      done: false
    }
  });
};

export const toggleTask = async (args, context) => {
  const { id } = args;
  if (!id) {
    throw new Error("Task id is required.");
  }
  const task = await context.entities.Task.findUnique({
    where: { id: Number(id) }
  });
  if (!task) {
    throw new Error(`Task with id ${id} not found.`);
  }
  return context.entities.Task.update({
    where: { id: Number(id) },
    data: {
      done: !task.done
    }
  });
};

